def make_palindrome(s: str) -> str:
    n = len(s)
    # Check if s is already a palindrome
    if s == s[::-1]:
        return s

    # Find the longest suffix that is a palindrome
    for k in range(n, 0, -1):
        suffix = s[-k:]
        if suffix == suffix[::-1]:
            prefix = s[:n - k]
            return s + prefix[::-1]

