def largest_prime_factor(n):
    max_factor = 0
    # Factor out all 2s
    while n % 2 == 0:
        max_factor = 2
        n = n // 2
    # Now n is odd
    f = 3
    while f * f <= n:
        if n % f == 0:
            max_factor = f
            n = n // f
        else:
            f += 2
    # If n is still greater than 1, it's a prime factor
    if n > 1:
        max_factor = n
    return max_factor

