    for letter in letters:
        count_dict[letter] = count_dict.get(letter, 0) + 1

    # Find max count
    max_count = max(count_dict.values()) if count_dict else 0

    # Collect all letters with max_count
    result = {}
    for letter, count in count_dict.items():
        if count == max_count:
            result[letter] = count

    return result

