def valid_date(date):
    if not date:
        return False
    parts = date.split('-')
    if len(parts) != 3:
        return False
    if len(parts[0]) != 2 or len(parts[1]) != 2 or len(parts[2]) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
    mm = int(parts[0])
    dd = int(parts[1])
    if mm < 1 or mm > 12:
        return False
    if dd < 1:
        return False
    if mm in [1, 3, 5, 7, 8, 10, 12]:
        if dd > 31:
            return False
    elif mm in [4, 6, 9, 11]:
        if dd > 30:
            return False
    else:
        if dd > 29:
            return False
    return True

