def minPath(grid, k):
    N = len(grid)
    start_i, start_j = 0, 0
    min_val = grid[0][0]
    for i in range(N):
        for j in range(N):
            if grid[i][j] < min_val:
                min_val = grid[i][j]
                start_i, start_j = i, j

    path = [min_val]
    current_i, current_j = start_i, start_j

    for _ in range(k-1):
        next_vals = []
        for di, dj in [(1,0), (-1,0), (0,1), (0,-1)]:
            ni = current_i + di
            nj = current_j + dj
            if 0 <= ni < N and 0 <= nj < N:
                next_vals.append((grid[ni][nj], ni, nj))
        next_val, next_i, next_j = min(next_vals, key=lambda x: x[0])
        path.append(next_val)
        current_i, current_j = next_i, next_j

    return path

